CREATE TABLE IF NOT EXISTS gps_points (
    -- @TableId(value = "id", type = IdType.AUTO)
    -- 在 PG 中，自增通常使用 BIGSERIAL (对应 Long) 或者 GENERATED BY DEFAULT AS IDENTITY
    id BIGSERIAL PRIMARY KEY,

    -- @TableField("track_id")
    -- Long 对应 BIGINT
    track_id BIGINT,

    -- @TableField("latitude")
    -- Double 对应 DOUBLE PRECISION
    latitude DOUBLE PRECISION,

    -- @TableField("longitude")
    longitude DOUBLE PRECISION,

    -- @TableField("altitude")
    altitude DOUBLE PRECISION,

    -- @TableField("timestamp")
    -- LocalDateTime 对应 TIMESTAMP (不带时区)
    timestamp TIMESTAMP,

    -- @TableField("speed")
    speed DOUBLE PRECISION
);

-- 可选：为常用查询字段添加索引（例如按轨迹ID或时间查询）
CREATE INDEX IF NOT EXISTS idx_gps_points_track_id ON gps_points(track_id);
CREATE INDEX IF NOT EXISTS idx_gps_points_timestamp ON gps_points(timestamp);

-- 添加注释（可选，是个好习惯）
COMMENT ON TABLE gps_points IS 'GPS轨迹点数据表';
COMMENT ON COLUMN gps_points.id IS '主键ID';
COMMENT ON COLUMN gps_points.track_id IS '轨迹ID';
COMMENT ON COLUMN gps_points.latitude IS '纬度';
COMMENT ON COLUMN gps_points.longitude IS '经度';
COMMENT ON COLUMN gps_points.altitude IS '海拔(米)';
COMMENT ON COLUMN gps_points.timestamp IS '记录时间';
COMMENT ON COLUMN gps_points.speed IS '速度(km/h)';